CREATE TYPE public.app_role AS ENUM ('admin','cook','user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, nome text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_own_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,nome) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'nome',NEW.raw_user_meta_data->>'full_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END $$;
CREATE TRIGGER chefbox_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.cozinheiras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, nome text NOT NULL, email text NOT NULL, telefone text NOT NULL, especialidade text NOT NULL CHECK(especialidade IN('caseira','fit')), ponto_retirada text NOT NULL, capacidade integer NOT NULL DEFAULT 100 CHECK(capacidade>0), ativo boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.cozinheiras TO authenticated; GRANT ALL ON public.cozinheiras TO service_role;
ALTER TABLE public.cozinheiras ENABLE ROW LEVEL SECURITY;
CREATE POLICY cooks_read ON public.cozinheiras FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR user_id=auth.uid());
CREATE POLICY cooks_admin ON public.cozinheiras FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.pedidos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, cliente_nome text NOT NULL, cliente_email text NOT NULL, cliente_telefone text NOT NULL, linha text NOT NULL CHECK(linha IN('caseira','fit')), qtd_marmitas integer NOT NULL CHECK(qtd_marmitas IN(5,10)), restricoes text[] NOT NULL DEFAULT '{}', tipo_recebimento text NOT NULL CHECK(tipo_recebimento IN('entrega','retirada')), endereco text NOT NULL DEFAULT '', bairro text NOT NULL DEFAULT '', valor_total numeric(10,2) NOT NULL, status text NOT NULL DEFAULT 'aguardando_aprovacao' CHECK(status IN('aguardando_aprovacao','aprovado','em_preparo','saiu_entrega','pronto_retirada','concluido')), cozinheira_id uuid REFERENCES public.cozinheiras(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.pedidos TO authenticated; GRANT ALL ON public.pedidos TO service_role;
ALTER TABLE public.pedidos ENABLE ROW LEVEL SECURITY;
CREATE POLICY orders_read ON public.pedidos FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (status <> 'aguardando_aprovacao' AND EXISTS(SELECT 1 FROM public.cozinheiras c WHERE c.id=cozinheira_id AND c.user_id=auth.uid())));
CREATE POLICY orders_admin_update ON public.pedidos FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.notificacoes_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), pedido_id uuid REFERENCES public.pedidos(id), tipo text NOT NULL CHECK(tipo IN('email','whatsapp')), destinatario text NOT NULL, assunto text NOT NULL, conteudo text NOT NULL, status text NOT NULL DEFAULT 'simulado', enviado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.notificacoes_log TO authenticated; GRANT ALL ON public.notificacoes_log TO service_role;
ALTER TABLE public.notificacoes_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_admin ON public.notificacoes_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.chefbox_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), whatsapp text NOT NULL DEFAULT '', retirada text NOT NULL DEFAULT 'Ponto de retirada a confirmar', admin_email text NOT NULL DEFAULT '');
GRANT SELECT ON public.chefbox_settings TO anon; GRANT SELECT, UPDATE ON public.chefbox_settings TO authenticated; GRANT ALL ON public.chefbox_settings TO service_role;
ALTER TABLE public.chefbox_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.chefbox_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY settings_admin ON public.chefbox_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
